 void passiveAndForegroundResponsesStayIndependentAndFailureClearsBoth(){
  const auto engine=qEnvironmentVariable("RAISING_ENGINE_ROOT",QDir::currentPath());QTemporaryDir tmp(engine+"/.cache/qt-bridge-passive-XXXXXX");QVERIFY(tmp.isValid());QVERIFY(QDir().mkpath(tmp.path()+"/apps/qt-studio"));QFile script(tmp.path()+"/apps/qt-studio/service.mjs");QVERIFY(script.open(QIODevice::WriteOnly));script.write("import readline from 'node:readline';const lines=readline.createInterface({input:process.stdin});lines.on('line',line=>{const r=JSON.parse(line);if(r.method==='exit'){setTimeout(()=>process.exit(3),30);return;}setTimeout(()=>process.stdout.write(JSON.stringify({id:r.id,error:null,method:r.method})+'\\n'),r.method==='slow'?200:r.method==='pending'?2000:20);});");script.close();StudioBridge bridge(tmp.path());QJsonObject passive,foreground;bridge.requestBackground("slow",{},[&](QJsonObject r){passive=r;});QVERIFY(bridge.backgroundBusy());QVERIFY(!bridge.busy());bridge.request("fast",{},[&](QJsonObject r){foreground=r;});QVERIFY(bridge.busy());bool blocked=false;bridge.request("duplicate",{},[&](QJsonObject r){blocked=!r.value("error").toString().isEmpty();});QVERIFY(blocked);blocked=false;bridge.requestBackground("duplicate",{},[&](QJsonObject r){blocked=!r.value("error").toString().isEmpty();});QVERIFY(blocked);QTRY_COMPARE_WITH_TIMEOUT(foreground.value("method").toString(),QString("fast"),3000);QVERIFY(passive.isEmpty());QTRY_COMPARE_WITH_TIMEOUT(passive.value("method").toString(),QString("slow"),3000);QVERIFY(!bridge.busy()&&!bridge.backgroundBusy());passive={};foreground={};bridge.requestBackground("exit",{},[&](QJsonObject r){passive=r;});bridge.request("pending",{},[&](QJsonObject r){foreground=r;});QTRY_VERIFY_WITH_TIMEOUT(!passive.value("error").toString().isEmpty()&&!foreground.value("error").toString().isEmpty(),3000);QVERIFY(!bridge.busy()&&!bridge.backgroundBusy());
 }
